@GetMapping(path = "/invoice/{id}")                    // stage 1: model (logical page)
ModelAndView invoice(@PathVariable long id) {
    Invoice model = service.load(id);
    return new ModelAndView("invoice", "invoice", model);  // stage 2 via resolver
}
